CREATE TABLE IF NOT EXISTS license_types(id TEXT PRIMARY KEY,key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS licenses(id TEXT PRIMARY KEY,license_type_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,originating_seller_user_id TEXT,status TEXT NOT NULL DEFAULT 'pending',starts_at TEXT,ends_at TEXT,billing_provider TEXT,billing_subscription_id TEXT,billing_status TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(license_type_id) REFERENCES license_types(id));
CREATE TABLE IF NOT EXISTS license_terms(id TEXT PRIMARY KEY,license_type_id TEXT NOT NULL,version TEXT NOT NULL,terms_content TEXT NOT NULL,effective_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',UNIQUE(license_type_id,version));
CREATE TABLE IF NOT EXISTS license_acceptances(id TEXT PRIMARY KEY,license_id TEXT NOT NULL,terms_id TEXT NOT NULL,user_id TEXT NOT NULL,accepted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS installations(id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL,license_id TEXT,installation_name TEXT,credential_hash TEXT,status TEXT NOT NULL DEFAULT 'active',last_verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS packages(id TEXT PRIMARY KEY,package_key TEXT NOT NULL,version TEXT NOT NULL,release_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',UNIQUE(package_key,version));